const require_browser = require("../utils/browser.js");
const require_defaults = require("../utils/defaults.js");
const require_index = require("../useMount/index.js");
let react = require("react");
//#region src/useKeyModifier/index.ts
const defaultEvents = [
	"mousedown",
	"mouseup",
	"keydown",
	"keyup"
];
const useKeyModifier = (modifier, options = require_defaults.defaultOptions) => {
	const { events = defaultEvents, initial = false } = options;
	const [state, setState] = (0, react.useState)(initial);
	require_index.useMount(() => {
		events.forEach((listenEvent) => {
			require_browser.on(document, listenEvent, (evt) => {
				if (typeof evt.getModifierState === "function") setState(evt.getModifierState(modifier));
			});
		});
		return () => {
			events.forEach((listenerEvent) => {
				require_browser.off(document, listenerEvent, (evt) => {
					if (typeof evt.getModifierState === "function") setState(evt.getModifierState(modifier));
				});
			});
		};
	});
	return state;
};
//#endregion
exports.useKeyModifier = useKeyModifier;
